//! One actual shared-reactor normal-profile Unix/TCP PILS service flow.
//! All keys are newly generated by this Rust test; no C key/daemon is accessed.
#![cfg(all(unix, feature = "service", feature = "client"))]
#![expect(
    clippy::panic_in_result_fn,
    reason = "Actual original service bytes, crypto, FIFO and physical retirement are independently checked"
)]
use gnunet_config::Configuration;
use gnunet_crypto::{EddsaPublicKey, EddsaSignature};
use gnunet_hello::Hello;
use gnunet_pils::{HelloLimits, Profile};
use gnunet_pils_host::{
    service::{Limits, Progress},
    startup,
};
use gnunet_service_runtime::{
    clock::{RuntimeClock, SystemClock},
    service::Listener,
};
use gnunet_session_crypto::exchange::{EcdhePublic, EcdheSecret, kem_encapsulate};
use gnunet_wire::official::{
    MessageHeader, SignaturePurpose,
    pils::{PeerUpdate, Request, Response},
};
use std::{
    error::Error,
    future::{Future, poll_fn},
    io,
    os::unix::ffi::OsStrExt,
    path::PathBuf,
    sync::Arc,
    task::Poll,
    time::Duration,
};
use tokio::{
    io::{AsyncRead, AsyncReadExt, AsyncWrite, AsyncWriteExt},
    net::{TcpListener, TcpStream, UnixListener, UnixStream},
    time::Instant,
};
use zeroize::Zeroizing;
type Failure = Box<dyn Error>;
struct Scratch(PathBuf);
impl Scratch {
    fn new() -> io::Result<Self> {
        let mut random = [0; 8];
        getrandom::fill(&mut random).map_err(io::Error::other)?;
        let path = std::env::temp_dir().join(format!("gprs-{:016x}", u64::from_be_bytes(random)));
        std::fs::create_dir(&path)?;
        Ok(Self(path))
    }
}
impl Drop for Scratch {
    fn drop(&mut self) {
        let _cleanup = std::fs::remove_dir_all(&self.0);
    }
}
fn hello_limits() -> HelloLimits {
    HelloLimits {
        maximum_input_bytes: 65535,
        maximum_address_bytes: 4096,
        maximum_addresses: 32,
    }
}
async fn frame(stream: &mut (impl AsyncRead + Unpin)) -> Result<Zeroizing<Vec<u8>>, Failure> {
    let mut header = [0; 4];
    stream.read_exact(&mut header).await?;
    let len = MessageHeader::decode(&header)?.size();
    if len < 4 {
        return Err("short PILS frame".into());
    }
    let mut bytes = Zeroizing::new(vec![0; len]);
    bytes[..4].copy_from_slice(&header);
    stream.read_exact(&mut bytes[4..]).await?;
    Ok(bytes)
}
async fn send(stream: &mut (impl AsyncWrite + Unpin), request: Request<'_>) -> Result<(), Failure> {
    let mut bytes = Zeroizing::new(vec![0; 65535]);
    let len = request.encode(&mut bytes)?;
    for part in bytes[..len].chunks(3) {
        stream.write_all(part).await?;
    }
    Ok(())
}
fn checked_update(
    bytes: &[u8],
    clock: &dyn RuntimeClock,
    count: usize,
) -> Result<[u8; 32], Failure> {
    checked_profile_update(bytes, clock, count, Profile::Reference029)
}
fn checked_profile_update(
    bytes: &[u8],
    clock: &dyn RuntimeClock,
    count: usize,
    profile: Profile,
) -> Result<[u8; 32], Failure> {
    let update = PeerUpdate::decode(bytes)?;
    let mut scratch = [0; 4096];
    let hello = Hello::parse_block(update.block, &mut scratch, hello_limits())?;
    hello.verify_at(profile.hello(), clock.sample()?.now)?;
    assert_eq!(hello.address_hash(profile.hello()), update.hash);
    assert_eq!(hello.addresses().count(), count);
    Ok(*hello.peer().as_bytes())
}
async fn original_clients(
    unix: PathBuf,
    tcp: std::net::SocketAddr,
    expected_peer: [u8; 32],
    clock: Arc<dyn RuntimeClock>,
) -> Result<(), Failure> {
    let mut a = UnixStream::connect(unix).await?;
    let mut b = TcpStream::connect(tcp).await?;
    let initial_a = frame(&mut a).await?;
    let initial_b = frame(&mut b).await?;
    assert_eq!(&*initial_a, &*initial_b);
    assert_eq!(
        checked_update(&initial_a, clock.as_ref(), 0)?,
        expected_peer
    );
    assert_eq!(
        checked_update(&initial_b, clock.as_ref(), 0)?,
        expected_peer
    );
    let mut region = [0x41; 48];
    SignaturePurpose::new(38, 40)?.encode(&mut region)?;
    send(
        &mut a,
        Request::Sign {
            request: 0x12345678,
            region: &region,
        },
    )
    .await?;
    // Pipeline a real FEED behind the original signature request. Its metadata
    // comes from the actual received signed HELLO; no test identity is forged.
    let initial = PeerUpdate::decode(&initial_a)?;
    let mut block = initial.block.to_vec();
    block.extend_from_slice(b"gnunet+tcp://127.0.0.1:1234\0");
    send(&mut a, Request::Feed { block: &block }).await?;
    let signed = frame(&mut a).await?;
    match Response::decode(&signed)? {
        Response::Signature {
            request,
            peer,
            signature,
        } => {
            assert_eq!(request, 0x12345678);
            assert_eq!(peer, expected_peer);
            EddsaPublicKey::from_bytes(peer).verify(
                38,
                &region,
                &EddsaSignature::from_bytes(signature),
            )?;
        }
        _ => return Err("original signature FIFO response missing".into()),
    }
    let updated_a = frame(&mut a).await?;
    let updated_b = frame(&mut b).await?;
    assert_eq!(&*updated_a, &*updated_b);
    assert_eq!(
        checked_update(&updated_a, clock.as_ref(), 1)?,
        expected_peer
    );
    assert_eq!(
        &PeerUpdate::decode(&updated_a)?.block[104..],
        b"gnunet+tcp://127.0.0.1:1234\0"
    );
    let ephemeral = EcdheSecret::from_bytes([7; 32]);
    let public = EcdhePublic::from_edwards(&expected_peer)?;
    let dh_expected = ephemeral.exchange_hashed(public)?.into_secret_bytes();
    send(
        &mut b,
        Request::Ecdh {
            request: 81,
            public: *ephemeral.public_key().as_bytes(),
        },
    )
    .await?;
    let dh = frame(&mut b).await?;
    match Response::decode(&dh)? {
        Response::Ecdh { request, key } => {
            assert_eq!(request, 81);
            assert_eq!(key, &*dh_expected);
        }
        _ => return Err("actual original DH response missing".into()),
    }
    let (encapsulation, secret) = kem_encapsulate(public, &ephemeral)?;
    let kem_expected = secret.into_secret_bytes();
    send(
        &mut a,
        Request::Decapsulate {
            request: 82,
            encapsulation: *encapsulation.as_bytes(),
        },
    )
    .await?;
    let kem = frame(&mut a).await?;
    match Response::decode(&kem)? {
        Response::Decapsulation { request, key } => {
            assert_eq!(request, 82);
            assert_eq!(key, &*kem_expected);
        }
        _ => return Err("actual original KEM response missing".into()),
    }
    Ok(())
}
#[test]
fn native_normal_service_all_handlers_fifo_crypto_and_restart() -> Result<(), Failure> {
    let scratch = Scratch::new()?;
    let mut config = Configuration::default();
    config.set_value(
        b"PEER",
        b"PRIVATE_KEY",
        Some(scratch.0.join("own-rust.key").as_os_str().as_bytes()),
    )?;
    config.set_value(b"PILS", b"UNIX_MATCH_UID", Some(b"YES"))?;
    config.set_value(b"PILS", b"UNIX_MATCH_GID", Some(b"YES"))?;
    let clock: Arc<dyn RuntimeClock> = Arc::new(SystemClock);
    let limits = Limits {
        clients: 2,
        io_slice_bytes: 7,
        address_bytes: 4096,
        addresses: 32,
        ..Limits::default()
    };
    // All actual seed creation and synchronization precedes runtime construction.
    let prepared = startup::prepare(&config, clock.clone(), limits)?;
    let peer = prepared
        .identity()
        .ok_or("missing actual prepared identity")?;
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()?;
    runtime.block_on(async {
        let mut host = prepared.into_host();
        let unix_path = scratch.0.join("p");
        let unix = UnixListener::bind(&unix_path)?;
        let tcp = TcpListener::bind("127.0.0.1:0").await?;
        let listeners = [Listener::Unix(&unix), Listener::Tcp(&tcp)];
        let mut client = std::pin::pin!(original_clients(
            unix_path,
            tcp.local_addr()?,
            peer,
            clock.clone()
        ));
        let deadline = Instant::now() + Duration::from_secs(5);
        let outcome = loop {
            let mut observe = |_| {};
            let mut driving = std::pin::pin!(host.drive(&listeners, &mut observe, Some(deadline)));
            let next = poll_fn(|cx| {
                if let Poll::Ready(result) = client.as_mut().poll(cx) {
                    return Poll::Ready(result.map(|()| None));
                }
                driving
                    .as_mut()
                    .poll(cx)
                    .map(|result| result.map(Some).map_err(|error| Box::new(error) as Failure))
            })
            .await;
            match next {
                Ok(None) => break Ok(()),
                Ok(Some(Progress::WaitDeadline)) => {
                    break Err("actual service flow timed out".into());
                }
                Ok(Some(Progress::AdmissionFailed { error, .. })) => {
                    break Err(Box::new(error) as Failure);
                }
                Ok(Some(_)) => {}
                Err(error) => break Err(error),
            }
        };
        host.close();
        outcome?;
        let report = host.report();
        assert_eq!(report.admitted, 2);
        assert_eq!(report.requests, 4);
        assert_eq!(report.broadcasts, 1);
        assert_eq!(report.identity_changes, 0);
        assert_eq!(report.crypto_failures, 0);
        assert_eq!(report.written_frames, 7);
        assert_eq!(report.closed, 2);
        assert_eq!(host.clients(), 0);
        assert_eq!(host.identity(), None);
        Ok::<_, Failure>(())
    })?;
    drop(runtime);
    // A new original writer derives the same identity from this test's actual
    // durable raw32. Only public identities are compared; private bytes are not logged.
    let reopened = startup::prepare(&config, clock, limits)?;
    assert_eq!(reopened.identity(), Some(peer));
    Ok(())
}

#[test]
fn configured_conditional_service_rotates_real_feed_and_keeps_original_signing_mq()
-> Result<(), Failure> {
    use std::os::unix::fs::PermissionsExt;
    let scratch = Scratch::new()?;
    std::fs::set_permissions(&scratch.0, std::fs::Permissions::from_mode(0o700))?;
    let key = scratch.0.join("conditional.key");
    let mut config = Configuration::default();
    config.set_value(b"PEER", b"PRIVATE_KEY", Some(key.as_os_str().as_bytes()))?;
    config.set_value(b"PILS", b"PROFILE", Some(b"invalid"))?;
    let clock: Arc<dyn RuntimeClock> = Arc::new(SystemClock);
    let limits = Limits {
        clients: 1,
        io_slice_bytes: 7,
        ..Limits::default()
    };
    assert!(startup::prepare(&config, clock.clone(), limits).is_err());
    assert!(
        !key.exists(),
        "invalid profile must not create private material"
    );
    config.set_value(b"PILS", b"PROFILE", Some(b"deterministic"))?;
    let prepared = startup::prepare(&config, clock.clone(), limits)?;
    let empty_peer = prepared
        .identity()
        .ok_or("conditional initial identity missing")?;
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()?;
    runtime.block_on(async {
        let mut host = prepared.into_host();
        let path = scratch.0.join("conditional");
        let listener = UnixListener::bind(&path)?;
        let listeners = [Listener::Unix(&listener)];
        let mut client = std::pin::pin!(async {
            let mut stream = UnixStream::connect(&path).await?;
            let initial = frame(&mut stream).await?;
            let profile = Profile::ReferenceDeterministic;
            assert_eq!(
                checked_profile_update(&initial, clock.as_ref(), 0, profile)?,
                empty_peer
            );
            let initial = PeerUpdate::decode(&initial)?;
            let empty = initial.block.to_vec();
            let mut addressed = empty.clone();
            addressed.extend_from_slice(b"gnunet+tcp://127.0.0.1:1234\0");
            send(&mut stream, Request::Feed { block: &addressed }).await?;
            let added = frame(&mut stream).await?;
            let address_peer = checked_profile_update(&added, clock.as_ref(), 1, profile)?;
            assert_ne!(address_peer, empty_peer);
            send(&mut stream, Request::Feed { block: &empty }).await?;
            let withdrawn = frame(&mut stream).await?;
            assert_eq!(
                checked_profile_update(&withdrawn, clock.as_ref(), 0, profile)?,
                empty_peer
            );
            send(&mut stream, Request::Feed { block: &addressed }).await?;
            let restored = frame(&mut stream).await?;
            assert_eq!(
                checked_profile_update(&restored, clock.as_ref(), 1, profile)?,
                address_peer
            );
            let mut region = [0x41; 48];
            SignaturePurpose::new(38, 40)?.encode(&mut region)?;
            send(
                &mut stream,
                Request::Sign {
                    request: 91,
                    region: &region,
                },
            )
            .await?;
            let result = frame(&mut stream).await?;
            match Response::decode(&result)? {
                Response::Signature {
                    request,
                    peer,
                    signature,
                } => {
                    assert_eq!(request, 91);
                    assert_eq!(peer, address_peer);
                    EddsaPublicKey::from_bytes(peer).verify(
                        38,
                        &region,
                        &EddsaSignature::from_bytes(signature),
                    )?;
                }
                _ => return Err("same conditional MQ did not return its actual signature".into()),
            }
            Ok::<_, Failure>(())
        });
        let deadline = Instant::now() + Duration::from_secs(5);
        let outcome = loop {
            let mut observe = |_| {};
            let mut driving = std::pin::pin!(host.drive(&listeners, &mut observe, Some(deadline)));
            let next = poll_fn(|cx| {
                if let Poll::Ready(result) = client.as_mut().poll(cx) {
                    return Poll::Ready(result.map(|()| None));
                }
                driving
                    .as_mut()
                    .poll(cx)
                    .map(|result| result.map(Some).map_err(|error| Box::new(error) as Failure))
            })
            .await;
            match next {
                Ok(None) => break Ok(()),
                Ok(Some(Progress::WaitDeadline)) => {
                    break Err("conditional native service flow timed out".into());
                }
                Ok(Some(Progress::AdmissionFailed { error, .. })) => {
                    break Err(Box::new(error) as Failure);
                }
                Ok(Some(_)) => {}
                Err(error) => break Err(error),
            }
        };
        host.close();
        outcome?;
        let report = host.report();
        assert_eq!(report.admitted, 1);
        assert_eq!(report.requests, 4);
        assert_eq!(report.identity_changes, 3);
        assert_eq!(report.broadcasts, 3);
        assert_eq!(report.written_frames, 5);
        assert_eq!(report.closed, 1);
        assert_eq!(host.clients(), 0);
        Ok::<_, Failure>(())
    })
}
